function usePersist(key,initial){const sandbox=useContext(TourSandboxContext);const [value,setValue]=useState(()=>{if(sandbox)return initial;try{return JSON.parse(localStorage.getItem('sales-demo-v1-'+key))??initial}catch{return initial}});useEffect(()=>{if(sandbox)return;try{localStorage.setItem('sales-demo-v1-'+key,JSON.stringify(value))}catch{}},[value,key,sandbox]);return [value,setValue]}
const uid=()=>globalThis.crypto?.randomUUID?.()??String(Date.now())+Math.random();
function IconButton({label,onClick,children,className=''}){return <button className={'icon-btn '+className} aria-label={label} title={label} onClick={onClick}>{children}</button>}
function Section({title,extra,children}){return <section className="section"><div className="section-head"><h2>{title}</h2>{extra}</div>{children}</section>}
function Pill({children,tone=''}){return <span className={'pill '+tone}>{children}</span>}
function TaskRow({task,toggle,detail}){return <div className={'task-row '+(task.done?'done':'')}><button aria-label={task.done?'Riapri '+task.title:'Completa '+task.title} aria-pressed={task.done} className={'check '+(task.done?'checked':'')} onClick={()=>toggle(task.id)}>{task.done&&<Check size={14}/>}</button><button className="task-main" onClick={()=>detail(task)}><strong>{task.title}</strong><small>{task.detail||task.account}</small><span className="task-account"><Building2 size={12}/>{task.account}</span></button><div className="task-meta"><span className={'due '+(task.due==='Oggi'?'urgent':'')}><Clock size={12}/>{task.due}</span><span className={'priority '+(task.priority==='Alta'?'high':'normal')}><i/>{task.priority||'Media'}</span></div></div>}
