 function save(){if(!account)return;const id=uid();const approved=facts.filter(f=>f.selected);const prior=new Set(notes.filter(n=>n.account===account).flatMap(n=>n.facts||[]));const newFactCount=new Set(approved.map(f=>f.text).filter(v=>!prior.has(v))).size;const next=[...tasks],created=[];proposals.filter(p=>p.selected).forEach((p,i)=>{if(!next.some(t=>!t.done&&t.account===account&&t.title.toLowerCase()===p.title.toLowerCase())){const task={...p,id:id+'-'+i,account,done:false,source:id};next.push(task);created.push(task)}});setNotes(old=>[{id,account,text,summary:sample?'Interesse per TiPOS e richiesta di proposta economica.':text.trim().slice(0,180)||'Acquisizione documentale · '+attachments.map(a=>a.name).join(', '),facts:approved.map(f=>f.text),evidence:approved.map(f=>({text:f.text,source:f.source})),attachments:attachments.map(({id,name,type,size,demo})=>({id,name,type,size,demo})),date:'Appena ora'},...old]);setTasks(next);if(captureVisit&&VISITS.some(v=>v.id===captureVisit&&v.account===account))setVisitStates(old=>({...old,[captureVisit]:'done'}));setReceipt({id,account,newFacts:newFactCount,approvedFacts:approved.length,created,proposal:created.find(t=>/proposta|presentazion/i.test(t.title))||next.find(t=>t.account===account&&!t.done&&/proposta|presentazion/i.test(t.title)),followup:created.find(t=>/follow.up|richiam|contatt/i.test(t.title))||next.find(t=>t.account===account&&!t.done&&/follow.up|richiam|contatt/i.test(t.title))});setCaptureDraft(null);setAttachments([]);setText('');setElapsed(0);setCaptureVisit(null);go('success');if(account==='Bar Centrale')tour?.onEvent('note-saved')}
